        Situacao novaSituacao = null;

        switch (situacaoAtual) {
            case AGUARDANDO_PAGAMENTO:
                if (acao == Acao.PAGAR) {
                    novaSituacao = Situacao.PAGO;
                } else if (acao == Acao.CANCELAR) {
