                    }
                    pedido.setValorReembolsado(reembolso);
                    pedido.setEstoqueDevolvido(true);
                }
                break;

            case ENVIADO:
                if (acao == Acao.ENTREGAR) {
                    novaSituacao = Situacao.ENTREGUE;
